{"tool": "write_file", "args": {"content": """"Ops script: SENDS SMS. Re-sends each delivery text that the gateway recorded as failed.

Run from the Lifeline root:  python scripts/resend_failed_sms.py

This script appends new lines to data/outbox/sms.jsonl (the SMS gateway sends every
line in that file). Only messages whose recorded status is 'failed' are resent;
households whose original message was delivered are NOT texted again.
"""

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from notifications.sms import queue_sms, sent_messages  # noqa: E402
from core import store  # noqa: E402


def main() -> None:
    status = store.read_json("sms_status.json")
    by_id = {m.id: m for m in sent_messages()}

    resent = []
    for sms_id, result in status.items():
        if result != "failed":
            continue  # skip delivered (and any other) statuses
        original = by_id.get(sms_id)
        if original is None:
            continue  # original message missing; nothing to resend
        new_message = queue_sms(original.household_id, original.template_id, original.params)
        resent.append((sms_id, new_message.id))

    print(f"resent {len(resent)} failed SMS")
    for old_id, new_id in resent:
        print(f"{old_id} -> {new_id}")


if __name__ == "__main__":
    main()
